// One Cloudflare Worker serves the Next.js app, scheduled monitoring, and
// the internal SMTP transport. OpenNext does not bundle the SMTP socket API.
// @ts-ignore Generated by OpenNext during the build.
import handler from "./.open-next/worker.js";
import { runScheduledChecks } from "./src/lib/monitoring-engine";
import { deliverViaZoho } from "./src/lib/worker-smtp";
import type { MonitoringEnv } from "./src/lib/server/monitoring-db";

type ScheduledEvent = { scheduledTime: number; cron: string };
type WorkerContext = { waitUntil(promise: Promise<unknown>): void };

async function internalSmtp(request: Request, env: MonitoringEnv): Promise<Response> {
  // This route is handled before Next.js, and requires a deployment secret.
  // The secret is forwarded solely over WORKER_SELF_REFERENCE (not public HTTP).
  if (request.method !== "POST" || !env.JWT_SECRET || env.JWT_SECRET.length < 32 ||
      request.headers.get("x-biosec-smtp-secret") !== env.JWT_SECRET) {
    return new Response(null, { status: 404 });
  }
  if (env.SMTP_ENABLED !== "true") {
    return Response.json({ error: "SMTP is disabled" }, { status: 409 });
  }
  const size = Number(request.headers.get("content-length") || "0");
  if (size > 24000) return Response.json({ error: "Request exceeds allowed size" }, { status: 413 });
  let input: unknown;
  try { input = await request.json(); } catch {
    return Response.json({ error: "Invalid request" }, { status: 400 });
  }
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return Response.json({ error: "Invalid request body" }, { status: 400 });
  }
  const data = input as Record<string, unknown>;
  if (!Array.isArray(data.recipients) || !data.recipients.length ||
      data.recipients.length > 10 ||
      data.recipients.some(v => typeof v !== "string" ||
        !/^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(v)) ||
      typeof data.subject !== "string" || data.subject.length > 180 ||
      typeof data.body !== "string" || data.body.length > 12000) {
    return Response.json({ error: "Invalid SMTP payload" }, { status: 400 });
  }
  try {
    await deliverViaZoho(env, data.recipients as string[], data.subject, data.body);
    return Response.json({ accepted: true });
  } catch (error) {
    // Return the failure class without exposing credentials or message bodies.
    const message = error instanceof Error ? error.message : "SMTP transport failed";
    console.error("SMTP delivery error", message);
    return Response.json({ error: message.slice(0, 200) }, { status: 502 });
  }
}

export default {
  async fetch(request: Request, env: MonitoringEnv, ctx: WorkerContext) {
    if (new URL(request.url).pathname === "/__internal/smtp-delivery") {
      return internalSmtp(request, env);
    }
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_event: ScheduledEvent, env: MonitoringEnv, ctx: WorkerContext) {
    ctx.waitUntil(runScheduledChecks(env));
  },
};
